package com.cinenest.payments.internal;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.assertj.core.api.Assertions.*;
class BankInstructionPublicationPolicyTest {
 static MockEnvironment env(String... profiles){var e=new MockEnvironment().withProperty("cinenest.bank.instruction-publication.enabled","true").withProperty("cinenest.bank.instruction-publication.mode","STAGING_ONLY");e.setActiveProfiles(profiles);return e;}
 static Map<String,Object> draft(){var b=new LinkedHashMap<String,Object>();b.put("commandKey",UUID.randomUUID().toString());b.put("expectedRevision",0);b.put("instructionVersion","SYNTHETIC-PUBLICATION");b.put("reference",FixedInstructionResolver.REFERENCE.toString());b.put("referenceVersion",FixedInstructionResolver.VERSION1.toString());b.put("contentSha256",FixedInstructionResolver.digest(FixedInstructionResolver.VERSION1));b.put("effectiveFrom","2030-01-02T00:00:00Z");b.put("effectiveUntil","2030-01-03T00:00:00Z");return b;}
 @Test void exactSyntheticProfilesAndModeOnly(){for(var p:List.of(new String[]{"synthetic-quotation"},new String[]{"local-synthetic","synthetic-quotation"},new String[]{"synthetic-quotation","local-synthetic"}))assertThatCode(()->new BankInstructionPublicationPolicy(env(p)).configured()).doesNotThrowAnyException();for(var p:List.of(new String[]{},new String[]{"local-synthetic"},new String[]{"production"},new String[]{"synthetic-quotation","unknown"}))assertThatThrownBy(()->new BankInstructionPublicationPolicy(env(p)).configured()).isInstanceOf(BankFailure.class);assertThatThrownBy(()->new BankInstructionPublicationPolicy(env("synthetic-quotation").withProperty("cinenest.bank.instruction-publication.mode","REAL")).configured()).isInstanceOf(BankFailure.class);}
 @Test void disabledByDefault(){assertThatThrownBy(()->new BankInstructionPublicationPolicy(new MockEnvironment()).configured()).isInstanceOf(BankFailure.class);}
 @Test void onlyClosedNonPayableReferencesAllowed(){var p=new BankInstructionPublicationPolicy(env("synthetic-quotation"));var b=draft();assertThat(p.draft(b).hash()).hasSize(64);for(String field:List.of("reference","referenceVersion","contentSha256")){var changed=new LinkedHashMap<>(b);changed.put(field,field.equals("contentSha256")?"a".repeat(64):UUID.randomUUID().toString());assertThatThrownBy(()->p.draft(changed)).isInstanceOf(BankFailure.class);}b.put("accountNumber","REAL-NOT-ALLOWED");assertThatThrownBy(()->p.draft(b)).isInstanceOf(BankFailure.class);}
 @Test void exactKeysRevisionAndTimeBounds(){var p=new BankInstructionPublicationPolicy(env("synthetic-quotation"));for(var value:List.of(-1,1,0.0,"0")){var b=draft();b.put("expectedRevision",value);assertThatThrownBy(()->p.draft(b)).isInstanceOf(BankFailure.class);}var b=draft();b.put("effectiveUntil",b.get("effectiveFrom"));assertThatThrownBy(()->p.draft(b)).isInstanceOf(BankFailure.class);}
 @Test void immutableSnapshotHashIncludesScheduleAndVersionNotCommandIdentity(){var p=new BankInstructionPublicationPolicy(env("synthetic-quotation"));var a=draft();var b=new LinkedHashMap<>(a);b.put("commandKey",UUID.randomUUID().toString());assertThat(p.draft(a).hash()).isEqualTo(p.draft(b).hash());b.put("effectiveUntil","2030-01-04T00:00:00Z");assertThat(p.draft(a).hash()).isNotEqualTo(p.draft(b).hash());}
 @Test void duplicateJsonOversizeAndTrailingObjectsRejected(){var p=new BankInstructionPublicationPolicy(env("synthetic-quotation"));for(String s:List.of("{\"x\":1,\"x\":2}","{}{}","[]"))assertThatThrownBy(()->p.parse(s.getBytes(java.nio.charset.StandardCharsets.UTF_8))).isInstanceOf(BankFailure.class);assertThatThrownBy(()->p.parse(new byte[16385])).isInstanceOf(BankFailure.class);}
 @Test void receiptAdmissionStaysUnconditionallyDenied(){var p=new ReceiptAdmissionPolicy();assertThat(p.decision()).isEqualTo(ReceiptAdmissionPolicy.Decision.DENY);assertThatThrownBy(p::requireAdmission).isInstanceOf(BankFailure.class);}
}
